def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            colors = set()
            while q:
                y, x = q.popleft()
                comp.append((y, x))
                if grid[y][x] > 1:
                    colors.add(grid[y][x])
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy, xx = y+dy, x+dx
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] != 0 and (yy,xx) not in seen:
                        seen.add((yy,xx))
                        q.append((yy,xx))
            if colors:
                color = min(colors)
                for y, x in comp:
                    if grid[y][x] != 1:
                        continue
                    if all(0 <= y+dy < h and 0 <= x+dx < w and grid[y+dy][x+dx] != 0
                           for dy in (-1,0,1) for dx in (-1,0,1)):
                        out[y][x] = color
    return out
'''
